{"content": "from typing import Annotated, List, Union

from pydantic import BaseModel, Field


class Metric(BaseModel):
    name: str
    # Numeric when it parses as an int, otherwise a label (e.g. "n/a").
    # Pydantic v2 defaults to "smart" union mode, which would keep the string "42"
    # as a str. left_to_right matches v1 behavior: try int first, then fall back to str.
    value: Annotated[Union[int, str], Field(union_mode="left_to_right")]


def parse_csv_row(row: str) -> Metric:
    name, value = row.split(",", 1)
    return Metric.model_validate({"name": name.strip(), "value": value.strip()})


def numeric_total(metrics: List[Metric]) -> int:
    return sum(m.value for m in metrics if isinstance(m.value, int))
